          longDescription:'English 9 is a first-year high-school English Language Arts course aligned to the Common Core State Standards for Grades 9–10. Unit 1, The Short Story, uses public-domain classics by O. Henry and Edgar Allan Poe to build close reading (plot, conflict, complex characters, theme, textual evidence, point of view, structure and suspense) and narrative writing. Later units cover poetry and figurative language, argument and rhetoric, Shakespearean drama, the epic and the hero’s journey, and research writing. Every lesson builds listening, speaking, reading and writing, with worked examples, practice at several levels, a quiz, a workshop activity, an assignment with a four-level rubric, and a review.',
