    <div style="background:#10233d;padding:20px;border-radius:14px;margin-bottom:20px;border:1px solid #33415c;">
    <h3 style="color:#bbdefb;margin-top:0;">🔑 Key Points from the Topic</h3>
    <ol style="margin:6px 0;padding-left:22px;">
    <li>Point of view may be first person, second person or third person (limited, omniscient or objective).</li>
    <li>An unreliable narrator cannot be fully trusted; his own words may contradict him.</li>
    <li>Dramatic irony lets the reader know more than a character.</li>
    <li>Structure and pacing — repeated events, slowed peaks, short sentences and an ending at the peak — build suspense.</li>
    <li>Figurative language such as similes and metaphors makes images and sounds vivid.</li>
    <li>Strong narrative scenes use a hook, build, peak and turn, show rather than tell, and punctuate dialogue correctly.</li>
    </ol>
    </div>
